describe('Modal Title Announcement', () => {
  beforeEach(() => {
    cy.visit('/modal');
  });

  it('should announce modal title when modal is opened', () => {
    // Verify modal is not visible initially
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();

    // Verify modal is now visible
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify modal title is announced
    cy.get('[data-testid="announce-modal-title"]').should('be.visible');
    cy.get('[data-testid="announce-modal-title"]').should('contain', 'Modal Title');

    // Verify modal content is visible
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify modal is closed
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is hidden again
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should announce modal title when modal is closed by pressing escape key', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify modal title is announced
    cy.get('[data-testid="announce-modal-title"]').should('be.visible');
    cy.get('[data-testid="announce-modal-title"]').should('contain', 'Modal Title');

    // Press escape key to close modal
    cy.get('body').type('{esc}');

    // Verify modal is closed
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Verify modal title is no longer announced
    cy.get('[data-testid="announce-modal-title"]').should('not.exist');
  });
});
